SELECT '1. 5 支指紋不變、仍為 SECURITY DEFINER' AS item, (SELECT count(*) FROM pg_proc p WHERE p.prosecdef AND ((p.oid = to_regprocedure('public.claim_hotelnabe_ari_push_batch(integer)') AND md5(replace(p.prosrc, E'\r', '')) = '57f53b0ba67d5f99f17a45640c11436d') OR (p.oid = to_regprocedure('public.gbp_vault_get(text)') AND md5(replace(p.prosrc, E'\r', '')) = 'c1faaca8da4aac41a2f9792be509c8bf') OR (p.oid = to_regprocedure('public.gbp_vault_set(text, text)') AND md5(replace(p.prosrc, E'\r', '')) = 'f574dbcf36712fb298fe180fc984d792') OR (p.oid = to_regprocedure('public.get_ai_ops_metrics(uuid, integer)') AND md5(replace(p.prosrc, E'\r', '')) = '670f67a22d8e7140fbb14365625acb51') OR (p.oid = to_regprocedure('public.get_rpc_contract(text[])') AND md5(replace(p.prosrc, E'\r', '')) = '442016e1eba30d3bcbb21d3608f4a3e4'))) = 5 AS ok
UNION ALL SELECT '2. 前 4 支 anon、authenticated 不可執行，service_role、postgres 可執行', (SELECT count(*) FROM pg_proc p WHERE p.oid IN (to_regprocedure('public.claim_hotelnabe_ari_push_batch(integer)'), to_regprocedure('public.gbp_vault_get(text)'), to_regprocedure('public.gbp_vault_set(text, text)'), to_regprocedure('public.get_rpc_contract(text[])')) AND NOT has_function_privilege('anon', p.oid, 'EXECUTE') AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE') AND has_function_privilege('service_role', p.oid, 'EXECUTE') AND has_function_privilege('postgres', p.oid, 'EXECUTE')) = 4
UNION ALL SELECT '3. get_ai_ops_metrics anon 不可；authenticated、service_role 可', (SELECT NOT has_function_privilege('anon', p.oid, 'EXECUTE') AND has_function_privilege('authenticated', p.oid, 'EXECUTE') AND has_function_privilege('service_role', p.oid, 'EXECUTE') FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ai_ops_metrics(uuid, integer)'))
UNION ALL SELECT '4. 5 支授權清單皆無 PUBLIC', NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a WHERE p.oid IN (to_regprocedure('public.claim_hotelnabe_ari_push_batch(integer)'), to_regprocedure('public.gbp_vault_get(text)'), to_regprocedure('public.gbp_vault_set(text, text)'), to_regprocedure('public.get_ai_ops_metrics(uuid, integer)'), to_regprocedure('public.get_rpc_contract(text[])')) AND a.grantee = 0)
UNION ALL SELECT '5. 5 支仍保有 sandbox_exec_* 執行權（未被變動）', (SELECT count(*) FROM pg_proc p WHERE p.oid IN (to_regprocedure('public.claim_hotelnabe_ari_push_batch(integer)'), to_regprocedure('public.gbp_vault_get(text)'), to_regprocedure('public.gbp_vault_set(text, text)'), to_regprocedure('public.get_ai_ops_metrics(uuid, integer)'), to_regprocedure('public.get_rpc_contract(text[])')) AND EXISTS (SELECT 1 FROM aclexplode(p.proacl) a JOIN pg_roles r ON r.oid = a.grantee WHERE r.rolname LIKE 'sandbox_exec_%' AND a.privilege_type = 'EXECUTE')) = 5;

SELECT p.oid::regprocedure::text AS func, COALESCE(p.proacl::text, 'NULL') AS proacl_after, md5(replace(p.prosrc, E'\r', '')) AS fp, has_function_privilege('anon', p.oid, 'EXECUTE') AS anon_exec, has_function_privilege('authenticated', p.oid, 'EXECUTE') AS auth_exec, has_function_privilege('service_role', p.oid, 'EXECUTE') AS service_exec
FROM pg_proc p
WHERE p.oid IN (to_regprocedure('public.claim_hotelnabe_ari_push_batch(integer)'), to_regprocedure('public.gbp_vault_get(text)'), to_regprocedure('public.gbp_vault_set(text, text)'), to_regprocedure('public.get_ai_ops_metrics(uuid, integer)'), to_regprocedure('public.get_rpc_contract(text[])'))
ORDER BY 1;
